custom_css:
/* ============================================================
 * Gruvbox Dark + HarmonyOS Sans SC
 * 从零编写，不基于任何模板
 * ============================================================ */

/* ---字体加载--- */
@import url('https://cdn.jsdelivr.net/npm/@lobehub/webfont-harmony-sans-sc@1.0.0/css/index-full.css');

/* ---字体变量--- */
:root {
  --font-sans: 'HarmonyOS Sans SC', system-ui, sans-serif;
  --font-serif: 'HarmonyOS Sans SC', system-ui, sans-serif;
  --font-mono: 'JetBrains Mono', 'Cascadia Code', ui-monospace, Menlo, Consolas, monospace;
}

/* ---全局字体（排除图标）--- */
body {
  font-family: var(--font-sans);
}

.mes_text,
.mes_text p,
.mes_text span,
.ch_name,
.mesIDDisplay,
.mes_timer,
.tokenCounterDisplay {
  font-family: var(--font-sans);
}

/* 代码等宽 */
code, pre, .hljs, .katex {
  font-family: var(--font-mono);
}

/* ============================================================
 * 引号文本 - 左竖线 + 底色 + 微缩进 组合拳
 * SillyTavern 用 <q> 标签包裹引号文字
 * ============================================================ */
.mes_text q {
  font-family: var(--font-serif) !important;
  color: var(--SmartThemeQuoteColor) !important;
  background: color-mix(in srgb, var(--SmartThemeQuoteColor) 10%, transparent);
  border-left: 3px solid var(--SmartThemeQuoteColor);
  padding: 2px 6px 2px 8px;
  margin: 0 2px;
  border-radius: 0 4px 4px 0;
  text-decoration: none !important;
}

/* blockquote 也留着以防有用 */
.mes_text blockquote {
  font-family: var(--font-serif) !important;
  border-left: 3px solid var(--SmartThemeQuoteColor);
  background: color-mix(in srgb, var(--SmartThemeQuoteColor) 10%, transparent);
  padding: 8px 12px 8px 14px;
  margin: 4px 0 4px 8px;
  border-radius: 0 4px 4px 0;
}

/* ============================================================
 * 代码块
 * ============================================================ */
code {
  background-color: var(--SmartThemeShadowColor);
  border-radius: 3px;
  padding: 1px 4px;
  font-size: 0.9em;
}

pre {
  background-color: var(--SmartThemeShadowColor) !important;
  border-radius: 6px;
  padding: 12px;
  overflow-x: auto;
}

pre code {
  background: transparent !important;
  padding: 0;
  border-radius: 0;
}

pre code.hljs {
  background: transparent !important;
}

.hljs {
  background: var(--SmartThemeShadowColor);
  border-radius: 6px;
}

/* ============================================================
 * 滚动条
 * ============================================================ */
::-webkit-scrollbar {
  width: 6px;
}
::-webkit-scrollbar:horizontal {
  height: 6px;
}
::-webkit-scrollbar-track {
  background: transparent;
}
::-webkit-scrollbar-thumb {
  background: color-mix(in srgb, var(--SmartThemeQuoteColor) 50%, transparent);
  border-radius: 3px;
}
::-webkit-scrollbar-thumb:hover {
  background: var(--SmartThemeQuoteColor);
}

/* ============================================================
 * 顶栏
 * ============================================================ */
#top-bar {
  background-color: transparent !important;
  box-shadow: 0 1px 0 var(--SmartThemeBorderColor);
}

#top-settings-holder {
  box-shadow: 0 1px 0 var(--SmartThemeQuoteColor);
}

.drawer {
  background-color: var(--SmartThemeBorderColor);
}

.drawer:has(.openDrawer) {
  background-color: var(--SmartThemeBlurTintColor);
}

.drawer-content {
  background-color: var(--SmartThemeBlurTintColor);
  border-radius: 0 0 6px 6px;
  box-shadow: 0 1px 0 var(--SmartThemeQuoteColor);
  border: 1px solid var(--SmartThemeBorderColor);
}

.drawer-icon {
  opacity: 0.5;
}

.drawer-icon:hover,
.drawer-icon.openIcon {
  opacity: 1;
}

/* ---抽屉标题--- */
.inline-drawer-header,
#top-settings-holder h4:not(#ai-config-button *):not(#rightNavHolder *) {
  border-left: 3px solid var(--SmartThemeQuoteColor);
  border-radius: 0;
  background-image: none !important;
  padding-left: 8px;
}

.inline-drawer-icon {
  font-size: var(--mainFontSize);
}

/* ---标题--- */
.standoutHeader strong,
#right-nav-panel h2,
.drawer-content h3.margin0,
.popup h3:not(dialog *) {
  font-size: calc(var(--mainFontSize) * 1.15);
  font-weight: 600;
  letter-spacing: 0.03em;
  line-height: 2;
}

.standoutHeader strong::before,
#right-nav-panel h2::before,
.drawer-content h3.margin0::before,
.popup h3:not(dialog *)::before {
  content: "◆";
  margin-right: 5px;
  color: var(--SmartThemeQuoteColor);
}

/* ============================================================
 * 输入框
 * ============================================================ */
input[type="text"],
input[type="number"],
input:not([type]),
textarea:not([type="search"]) {
  background-color: var(--SmartThemeShadowColor) !important;
  border: 1px solid var(--SmartThemeBorderColor) !important;
  border-radius: 4px;
}

input[type="text"]:focus,
input[type="number"]:focus,
input:not([type]):focus,
textarea:not([type="search"]):focus {
  border-color: var(--SmartThemeQuoteColor) !important;
}

textarea[type="search"] {
  background-color: transparent !important;
  border: none !important;
}

.text_pole {
  background-color: var(--SmartThemeShadowColor);
  border: 1px solid var(--SmartThemeBorderColor);
  border-radius: 4px;
}

/* ============================================================
 * 按钮
 * ============================================================ */
.menu_button {
  background-color: var(--SmartThemeShadowColor);
  border: 1px solid var(--SmartThemeBorderColor);
  color: var(--SmartThemeBodyColor);
  border-radius: 4px;
}

.menu_button:hover {
  background-color: color-mix(in srgb, var(--SmartThemeQuoteColor) 25%, var(--SmartThemeShadowColor));
  border-color: var(--SmartThemeQuoteColor);
}

#delete_button,
#dialogue_del_mes_ok,
#dialogue_popup_ok,
.redWarningBG,
.red_button,
.mes_edit_cancel.menu_button {
  background-color: rgba(204, 36, 29, 1) !important;
  color: #fff !important;
}

.mes_button,
.mes_edit_buttons {
  filter: none !important;
}

.fa-solid:not(#load-spinner) {
  text-shadow: none !important;
}

/* ============================================================
 * 下拉框
 * ============================================================ */
select {
  background-color: var(--SmartThemeShadowColor) !important;
  color: var(--SmartThemeBodyColor);
  border: 1px solid var(--SmartThemeBorderColor) !important;
  border-radius: 4px;
  margin: 4px 0 !important;
}

select option:checked {
  color: var(--SmartThemeBlurTintColor);
  background-color: var(--SmartThemeBodyColor) !important;
}

select option {
  background-color: var(--SmartThemeBlurTintColor) !important;
}

/* ============================================================
 * 勾选框
 * ============================================================ */
input[type="checkbox"] {
  width: calc(var(--mainFontSize) * 0.9);
  height: calc(var(--mainFontSize) * 0.9);
  border: none;
  border-radius: 3px;
  background-color: var(--SmartThemeShadowColor);
  filter: none;
  box-shadow: 0 0 0 1px var(--SmartThemeEmColor);
}

input[type="checkbox"]::before {
  box-shadow: inset 1em 1em var(--SmartThemeQuoteColor);
}

/* ============================================================
 * 滑动条
 * ============================================================ */
input[type="range"] {
  background-color: var(--SmartThemeShadowColor) !important;
  border-radius: 4px;
  box-shadow: none;
}

input[type="range"]::-webkit-slider-thumb {
  background-color: var(--SmartThemeQuoteColor);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--SmartThemeQuoteColor) 40%, transparent);
  border-radius: 50%;
  width: 10px;
  height: 10px;
}

/* ============================================================
 * 盒子/面板
 * ============================================================ */
#left-nav-panel,
#right-nav-panel,
#character_popup,
#dialogue_popup,
#chat,
.draggable,
#select_chat_popup,
.popup:not(.transparent_dialogue_popup),
.drawer-content {
  padding: 10px;
  background-color: var(--SmartThemeBlurTintColor);
  border-radius: 6px;
  border: 1px solid var(--SmartThemeBorderColor);
}

#left-nav-panel,
#right-nav-panel {
  height: 100dvh !important;
}

#dialogue_popup_text {
  padding: 0 10px 0 0;
}

/* ---列表--- */
.list-group,
.options-content {
  border: 1px solid var(--SmartThemeBorderColor);
  border-radius: 5px;
  background-color: var(--SmartThemeShadowColor) !important;
}

#options {
  background-color: transparent !important;
  padding: 0;
}

/* ---头像--- */
.avatar img,
body.big-avatars .avatar img {
  box-shadow: none;
  border: none;
  border-radius: 6px;
}

#rm_button_characters,
#rm_button_panel_pin_div,
#lm_button_panel_pin_div,
#WI_button_panel_pin_div {
  font-size: var(--mainFontSize);
}

/* ============================================================
 * 聊天区域
 * ============================================================ */
#sheld {
  top: calc(var(--topBarBlockSize));
  height: calc(100dvh - var(--topBarBlockSize) - 1px);
}

#chat {
  overflow-y: scroll;
  align-items: stretch;
  max-height: calc(100dvh - var(--topBarBlockSize) - 20px) !important;
  padding: 8px 8px 8px 8px;
  background-color: var(--SmartThemeChatTintColor);
}

.mesAvatarWrapper .avatar {
  margin: calc(var(--mainFontSize) * 0.6) 0 calc(var(--mainFontSize) * 0.4) 0;
}

.mesIDDisplay,
.mes_timer,
.tokenCounterDisplay {
  display: block;
  color: var(--SmartThemeEmColor);
  font-size: calc(var(--mainFontSize) * 0.75);
  opacity: 0.7;
}

#chat .ch_name {
  position: relative;
  align-items: flex-end;
  padding: calc(var(--mainFontSize) * 0.8) 0;
  font-weight: 500;
}

#chat .ch_name::after {
  content: "";
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  height: 1px;
  background-color: var(--SmartThemeEmColor);
}

.mes {
  border: none !important;
  background-color: var(--SmartThemeChatTintColor) !important;
}

.mes_text {
  padding: calc(var(--mainFontSize) * 0.8) 8px 0 0;
  line-height: 1.8;
}

.mes_block {
  padding-right: 8px;
}

.last_mes .mes_text {
  padding-right: 0;
}

.last_mes .mesAvatarWrapper {
  padding-bottom: 0;
}

div[is_user="false"].last_mes .mes_block {
  padding-bottom: 50px;
}

.last_mes .swipeRightBlock {
  margin: 0 10px 0 0;
}

div[is_user="true"] {
  background-color: var(--SmartThemeUserMesBlurTintColor) !important;
}

div[is_user="false"] {
  background-color: var(--SmartThemeBotMesBlurTintColor) !important;
}

div[is_user="true"] .avatar img {
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--SmartThemeUnderlineColor) 60%, transparent);
}

div[is_user="false"] .avatar img {
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--SmartThemeQuoteColor) 60%, transparent);
}

.swipe_left {
  left: 12px;
}

.swipeRightBlock {
  flex-direction: row-reverse;
  bottom: calc(var(--swipeCounterHeight) + var(--swipeCounterMargin));
}

#chat .mes.selected {
  background-color: rgba(204, 36, 29, 0.3) !important;
}

/* ---文档模式--- */
body.documentstyle #chat .ch_name::after { width: 0; }
body.documentstyle #chat .mes .mes_block { margin-right: 0; padding-bottom: 15px; }
body.documentstyle #chat .last_mes .mes_block { padding-bottom: 50px; }
body.documentstyle #chat .mes_text { margin-left: 0 !important; }

/* ---视觉小说模式--- */
body.waifuMode #chat {
  border: none;
  box-shadow: none;
  border-radius: 6px;
}
body.waifuMode .zoomed_avatar { top: 70px; }

/* ============================================================
 * 推理块
 * ============================================================ */
.mes_reasoning_header {
  margin: 1em 0;
  padding: 7px 28px 7px 10px;
  background: color-mix(in srgb, var(--SmartThemeQuoteColor) 20%, transparent);
  border: 1px solid var(--SmartThemeQuoteColor);
  border-radius: 4px;
  color: var(--SmartThemeBodyColor);
}

.mes_reasoning_header span::before {
  content: "◆";
  margin-right: 3px;
}

.mes_reasoning {
  border-left: 2px solid var(--SmartThemeQuoteColor);
}

/* ============================================================
 * 底栏
 * ============================================================ */
#form_sheld {
  margin: 0 auto;
}

#send_form {
  background-color: var(--SmartThemeBlurTintColor) !important;
  border: 1px solid var(--SmartThemeBorderColor) !important;
  border-radius: 6px;
  backdrop-filter: none;
  padding: 0 5px;
}

#send_form textarea {
  background-color: transparent !important;
  border: none !important;
}

#send_form .fa-solid {
  font-size: calc(var(--mainFontSize) * 1.2);
}

/* ---QR--- */
#qr--bar > .qr--buttons .qr--button,
#qr--popout > .qr--body > .qr--buttons .qr--button {
  background-color: color-mix(in srgb, var(--SmartThemeQuoteColor) 25%, transparent);
  border-color: var(--SmartThemeQuoteColor) !important;
  border-radius: 4px !important;
}

#qr--bar > .qr--buttons .qr--button:hover,
#qr--popout > .qr--body > .qr--buttons .qr--button:hover {
  background-color: color-mix(in srgb, var(--SmartThemeQuoteColor) 45%, transparent) !important;
}

/* ============================================================
 * 提示词管理器
 * ============================================================ */
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt {
  border-radius: 6px;
  background-color: var(--SmartThemeBlurTintColor);
}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt:hover,
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt:focus {
  border-color: var(--SmartThemeQuoteColor);
  background-color: color-mix(in srgb, var(--SmartThemeQuoteColor) 15%, transparent);
}

/* ============================================================
 * 世界书
 * ============================================================ */
.world_entry {
  margin-top: 5px;
}

.wi-card-entry {
  border: none;
}

.select2-container .select2-selection--multiple {
  background-color: var(--SmartThemeBlurTintColor);
  border: none;
  border-radius: 4px;
}

.select2-container .select2-selection--multiple .select2-selection__choice,
.select2-container .select2-selection--single .select2-selection__choice {
  background-color: color-mix(in srgb, var(--SmartThemeUnderlineColor) 25%, transparent);
  border-radius: 3px;
}

/* ============================================================
 * 角色管理器
 * ============================================================ */
.character_select.is_fav .avatar {
  outline: 2px solid var(--SmartThemeQuoteColor);
}

.character_select.is_fav .ch_name {
  color: var(--SmartThemeQuoteColor);
}

#HotSwapWrapper > div::-webkit-scrollbar-thumb {
  background-color: var(--SmartThemeBorderColor);
}

/* ---背景图库--- */
.bg_example {
  box-shadow: none;
  border-color: var(--SmartThemeBorderColor);
  border-radius: 4px;
}

.bg_example.selected {
  border-color: var(--SmartThemeUnderlineColor);
}

/* ============================================================
 * 移动端适配
 * ============================================================ */
@media screen and (max-width: 1000px) {
  #left-nav-panel,
  #right-nav-panel {
    height: calc(100dvh - 45px) !important;
    max-height: calc(100dvh - var(--topBarBlockSize)) !important;
    border-radius: 0 0 5px 5px;
  }
}

@supports (-webkit-touch-callout: none) {
  .drawer-content:not(#left-nav-panel):not(#right-nav-panel) {
    max-width: 100dvw;
    top: var(--topBarBlockSize);
  }
}

/* ============================================================
 * 标题下横线
 * ============================================================ */
.standoutHeader:not(h4),
#rm_PinAndTabs,
#top-settings-holder .drawer:not(:first-child):not(:last-child) .drawer-content .alignItemsBaseline.wide100p,
#rm_api_block .flex-container.alignItemsBaseline,
#title_api,
#AdvancedFormatting .flex-container.alignItemsBaseline:not(h3),
#WorldInfo .alignitemscenter:not(#world_popup *),
#Backgrounds .bg-header-row-1,
#user-settings-block div[name="userSettingsRowOne"],
#rm_extensions_block .alignitemscenter.flex-container.wide100p:not(.justifyCenter) {
  background-image: none;
  border: none;
  border-bottom: 1px solid var(--SmartThemeBorderColor);
  margin-bottom: calc(var(--mainFontSize) * 0.4);
  padding-bottom: calc(var(--mainFontSize) * 0.2);
}

.drawer-content .alignItemsBaseline {
  align-items: center !important;
}

#title_api {
  padding-bottom: 0;
}

#title_api::before,
#Backgrounds h3.margin0.flex2::before,
#rm_extensions_block .margin0.flex1::before,
#rm_button_selected_ch h2::before {
  margin-right: 5px;
}

.custom-mermaid {
  background-color: var(--SmartThemeShadowColor);
}

.standoutHeader.inline-drawer-header {
  padding: 5px 0;
}


/* ============================================================
 * 补回丢失的UI元素
 * ============================================================ */

/* ---世界书条目分割线--- */
.world_entry {
  border-bottom: 1px solid var(--SmartThemeBorderColor) !important;
  padding-bottom: 8px !important;
  margin-bottom: 8px !important;
}

.world_entry:last-child {
  border-bottom: none !important;
}

/* ---输入框边框--- */
#send_form {
  border: 1px solid var(--SmartThemeBorderColor) !important;
}

#send_textarea {
  border: 1px solid var(--SmartThemeBorderColor) !important;
  border-radius: 6px !important;
  padding: 8px 12px !important;
}

#send_textarea:focus {
  border-color: var(--SmartThemeQuoteColor) !important;
}

/* ---抽屉内部分割线--- */
.drawer-content .inline-drawer {
  border-bottom: 1px solid var(--SmartThemeBorderColor);
}

/* ---提示词管理器条目边框--- */
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt {
  border: 1px solid var(--SmartThemeBorderColor) !important;
}

/* ---角色列表条目分割线--- */
.character_select {
  border-bottom: 1px solid var(--SmartThemeBorderColor);
}

/* ---面板内分割线--- */
#right-nav-panel hr,
#left-nav-panel hr {
  border: none;
  border-top: 1px solid var(--SmartThemeBorderColor);
  margin: 8px 0;
}

/* ---设置区块分割--- */
#user-settings-block .setting_section {
  border-bottom: 1px solid var(--SmartThemeBorderColor);
  padding-bottom: 8px;
  margin-bottom: 8px;
}

/* ============================================================
 * 背景层 - v3.1 新增
 * body 底色 + #chat 透明 + 暗纹叠加
 * ============================================================ */

body {
  background-color: transparent !important;
}

/* 全屏暗色遮罩（聊天区域外） */
body::before {
  content: "";
  position: fixed;
  top: 0; left: 0; right: 0; bottom: 0;
  background-color: rgba(29, 32, 33, 0.92);
  pointer-events: none;
  z-index: 0;
}

/* 暗纹叠加层（在遮罩之上，聊天区之下） */
body::after {
  content: "";
  position: fixed;
  top: 0; left: 0; right: 0; bottom: 0;
  background-image:
    repeating-linear-gradient(45deg, transparent, transparent 35px, rgba(142, 192, 124, 0.008) 35px, rgba(142, 192, 124, 0.008) 70px),
    repeating-linear-gradient(-45deg, transparent, transparent 35px, rgba(131, 165, 152, 0.008) 35px, rgba(131, 165, 152, 0.008) 70px);
  pointer-events: none;
  z-index: 0;
}

/* #chat 用 JSON 字段的 chat_tint_color（已改为 0.75 透明） */
/* 消息背景透明，让 chat_tint 透过来 */
.mes {
  background-color: transparent !important;
}

div[is_user="true"],
div[is_user="false"] {
  background-color: transparent !important;
}

/* ============================================================
 * 图标悬停发光动效 - v3.2
 * ============================================================ */

/* 所有交互图标统一 transition */
.interactable,
.fa-solid:not(#load-spinner),
.drawer-icon,
.menu_button .fa-solid,
#send_form .fa-solid,
#send_form a,
#top-settings-holder .fa-solid,
#top-bar .fa-solid {
  transition: filter 0.35s ease-out, transform 0.35s ease-out;
}

/* 通用 hover 发光 + 放大 */
.interactable:hover,
.fa-solid:not(#load-spinner):hover,
.drawer-icon:hover,
#top-settings-holder .fa-solid:hover,
#top-bar .fa-solid:hover {
  filter: drop-shadow(0 0 4px rgba(142, 192, 124, 0.4));
  transform: scale(1.1);
}

/* 底部三按钮更强发光 + 放大 */
#send_form .fa-solid:hover,
#send_form a:hover {
  filter: drop-shadow(0 0 6px rgba(142, 192, 124, 0.6));
  transform: scale(1.1);
}

/* 按钮内图标放大 */
.menu_button:hover .fa-solid {
  transform: scale(1.1);
}

/* 角色头像悬停微光 */
.avatar img,
.character_select .avatar img {
  transition: filter 0.35s ease-out;
}

.avatar img:hover,
.character_select:hover .avatar img {
  filter: drop-shadow(0 0 6px rgba(142, 192, 124, 0.3));
}

/* ============================================================
 * 底部三按钮各自动效 - v3.3 新增
 * 汉堡菜单→抖动 / 魔杖→旋转 / 发送→书写摆动
 * ============================================================ */

/* --- 汉堡菜单：hover 抖动 --- */
#options_button .fa-solid,
#options_button {
  transition: filter 0.35s ease-out;
}

#options_button:hover .fa-solid,
#options_button:hover {
  animation: icon-shake 0.4s ease-in-out;
  filter: drop-shadow(0 0 4px rgba(142, 192, 124, 0.4));
}

@keyframes icon-shake {
  0%, 100% { transform: translateX(0) rotate(0); }
  20% { transform: translateX(-2px) rotate(-3deg); }
  40% { transform: translateX(2px) rotate(3deg); }
  60% { transform: translateX(-2px) rotate(-3deg); }
  80% { transform: translateX(2px) rotate(3deg); }
}

/* --- 魔杖：hover 旋转 --- */
#persona_button .fa-solid,
#persona_button,
#ru_button .fa-solid,
#ru_button {
  transition: filter 0.35s ease-out, transform 0.5s ease-out;
}

#persona_button:hover .fa-solid,
#persona_button:hover,
#ru_button:hover .fa-solid,
#ru_button:hover {
  filter: drop-shadow(0 0 4px rgba(142, 192, 124, 0.4));
  animation: icon-spin 0.6s ease-in-out;
}

@keyframes icon-spin {
  0% { transform: rotate(0); }
  100% { transform: rotate(360deg); }
}

/* --- 发送按钮：hover 发光 + active 变暗（不用transform防撑边框） --- */
#send_but {
  transition: filter 0.35s ease-out, opacity 0.2s ease-out;
